function dockThreshold(capacities, load) {
    for (let i = 0; i < capacities.length; i++)
        if (capacities[i] >= load)
            return i;
    return -1;
}

function dockThreshold(capacities, load) {
    let left = 0;
    let right = capacities.length;
    while (left < right) {
        const mid = left + Math.floor((right - left) / 2);
        if (capacities[mid] >= load)
            right = mid;
        else
            left = mid + 1;
    }
    return left === capacities.length ? -1 : left;
}
